-- Owner-selected terms only. No booking, invoice, redemption or activation occurs.
begin;
select pg_advisory_xact_lock(hashtextextended('canonical-loyalty-cron',0));
do $$
<<qa>>
declare own uuid;employee uuid;customer uuid;br uuid:=gen_random_uuid();service uuid:=gen_random_uuid();missing_service uuid:=gen_random_uuid();
 offer uuid;missing_offer uuid;policy uuid:=gen_random_uuid();missing_policy uuid:=gen_random_uuid();request uuid:=gen_random_uuid();second_request uuid:=gen_random_uuid();new_policy uuid:=gen_random_uuid();
 rules jsonb:='{"pooling":"policy_version","expiry":"no_expiry","cancellation":"restore_visits","refunded_contribution":"offset_future_visits"}';
 other_rules jsonb:='{"pooling":"offer_branch","expiry":"no_expiry","cancellation":"forfeit_visits","refunded_contribution":"freeze_for_owner_review"}';
 result jsonb;again jsonb;context jsonb;denied boolean;invoice_hash text;legacy_count bigint;earned_count bigint;activation_count bigint;outbox_count bigint;
begin
 select user_id into strict own from public.staff_profiles where role='owner' and is_active limit 1;
 select user_id into strict employee from public.staff_profiles where role='employee' and is_active limit 1;
 select c.id into strict customer from public.customers c where not exists(select 1 from public.staff_profiles s where s.user_id=c.id) limit 1;
 select md5(coalesce(string_agg(to_jsonb(i)::text,'' order by invoice_id),'')) into invoice_hash from public.business_invoices i;
 select count(*) into legacy_count from public.business_loyalty_transactions;
 select count(*) into earned_count from private.canonical_loyalty_visits;
 select count(*) into activation_count from private.loyalty_visit_activations;
 select count(*) into outbox_count from private.loyalty_visit_outbox;
 insert into public.business_branches(branch_id,name_ar,name_en) values(br,'اختبار قواعد الاستبدال','Redemption rules QA');
 insert into public.business_catalog_items(item_id,branch_id,item_type,name,price,is_active,is_public) values(service,br,'service','Actual configured reward QA',123,true,true);
 assert not has_table_privilege('authenticated','private.loyalty_redemption_rule_versions','SELECT');
 assert not has_table_privilege('service_role','private.loyalty_redemption_rule_versions','UPDATE');
 execute 'set local role anon';denied:=false;begin perform public.get_loyalty_redemption_rules(policy);exception when insufficient_privilege then denied:=true;end;assert denied;
 execute 'set local role authenticated';perform set_config('request.jwt.claim.sub',customer::text,true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',customer,'role','authenticated','user_metadata',jsonb_build_object('role','owner'))::text,true);
 denied:=false;begin perform public.save_loyalty_redemption_rules(request,policy,null,rules);exception when insufficient_privilege then denied:=true;end;assert denied,'Editable metadata impersonated owner';
 perform set_config('request.jwt.claim.sub',employee::text,true);denied:=false;begin perform public.get_loyalty_redemption_rules(policy);exception when insufficient_privilege then denied:=true;end;assert denied;
 perform set_config('request.jwt.claim.sub',own::text,true);
 result:=public.save_visit_reward_offer(gen_random_uuid(),br,'Owner configured explicit QA reward',7,true,service);offer:=(result->>'offer_id')::uuid;
 perform public.save_loyalty_policy(policy,br,offer,array[service],true);
 context:=public.get_loyalty_redemption_rules(policy);
 assert context->>'rules_saved'='false' and context->>'redemption_enabled'='false' and context->'current'='null'::jsonb,'Rules were selected implicitly';
 assert context->'save_blockers'='[]'::jsonb;
 assert (context->>'threshold_visits')::integer=7 and context->'reward_service'->>'id'=service::text;
 denied:=false;begin perform public.save_loyalty_redemption_rules(request,policy,null,rules-'expiry');exception when invalid_parameter_value then denied:=true;end;assert denied,'Missing choice silently defaulted';
 denied:=false;begin perform public.save_loyalty_redemption_rules(request,policy,null,rules||'{"pooling":"legacy_money"}');exception when invalid_parameter_value then denied:=true;end;assert denied,'Unsupported money conversion accepted';
 denied:=false;begin perform public.save_loyalty_redemption_rules(request,policy,null,rules||'{"enabled":true}');exception when invalid_parameter_value then denied:=true;end;assert denied,'Extra activation input accepted';
 denied:=false;begin perform public.save_loyalty_redemption_rules(request,policy,null,rules||'{"expiry":"snapshot_offer_end"}');exception when invalid_parameter_value then denied:=true;end;assert denied,'Missing frozen deadline invented';
 result:=public.save_loyalty_redemption_rules(request,policy,null,rules);
 again:=public.save_loyalty_redemption_rules(request,policy,null,rules);assert again=result,'Lost-response retry changed original saved result';
 assert result->>'rules_saved'='true' and result->>'terms_valid'='true' and result->>'redemption_enabled'='false';
 assert result->'current'->'rules'=rules;
 assert result->'blockers' @> '["redemption_quote_not_implemented","booking_redemption_not_implemented","visit_reservation_not_implemented","visit_consumption_not_implemented","visit_release_not_implemented","reward_invoice_document_state_not_implemented"]';
 denied:=false;begin perform public.save_loyalty_redemption_rules(request,policy,null,other_rules);exception when invalid_parameter_value then denied:=true;end;assert denied,'Request identity allowed changed financial terms';
 denied:=false;begin perform public.save_loyalty_redemption_rules(second_request,policy,null,other_rules);exception when serialization_failure then denied:=true;end;assert denied,'Stale rules editor overwrote current terms';
 context:=public.save_loyalty_redemption_rules(second_request,policy,request,other_rules);assert jsonb_array_length(context->'history')=2;
 assert context->'blockers' @> '["owner_refund_review_resolution_not_implemented"]';
 assert public.save_loyalty_redemption_rules(request,policy,null,rules)=result,'Later version changed a prior request receipt';
 execute 'reset role';
 denied:=false;begin update private.loyalty_redemption_rule_versions set rules=other_rules where rules_version_id=request;exception when raise_exception then denied:=true;end;assert denied,'Rules history is mutable';
 denied:=false;begin delete from private.loyalty_redemption_rule_requests where request_id=request;exception when raise_exception then denied:=true;end;assert denied,'Request audit could be removed';
 assert exists(select 1 from public.business_audit_log where action='save_loyalty_redemption_rules' and entity_id=policy::text and before_data->>'rules_version_id'=request::text and after_data->>'rules_version_id'=second_request::text);
 update public.business_catalog_items set is_active=false where item_id=service;
 execute 'set local role authenticated';context:=public.get_loyalty_redemption_rules(policy);assert context->>'terms_valid'='false' and context->'save_blockers' @> '["reward_service_unavailable"]';
 denied:=false;begin perform public.save_loyalty_redemption_rules(gen_random_uuid(),policy,second_request,rules);exception when object_not_in_prerequisite_state then denied:=true;end;assert denied;
 execute 'reset role';update public.business_catalog_items set is_active=true where item_id=service;
 update public.business_offers set visits_required=8 where offer_id=offer;
 execute 'set local role authenticated';context:=public.get_loyalty_redemption_rules(policy);assert context->'save_blockers' @> '["offer_terms_changed"]';
 denied:=false;begin perform public.save_loyalty_redemption_rules(gen_random_uuid(),policy,second_request,rules);exception when object_not_in_prerequisite_state then denied:=true;end;assert denied;
 execute 'reset role';update public.business_offers set visits_required=7,ends_at=clock_timestamp()+interval '30 days' where offer_id=offer;
 execute 'set local role authenticated';perform public.save_loyalty_policy(new_policy,br,offer,array[service],true);
 denied:=false;begin perform public.save_loyalty_redemption_rules(gen_random_uuid(),policy,second_request,rules);exception when object_not_in_prerequisite_state then denied:=true;end;assert denied,'Rules saved against superseded policy';
 context:=public.save_loyalty_redemption_rules(gen_random_uuid(),new_policy,null,rules||'{"expiry":"snapshot_offer_end"}');assert context->>'redemption_enabled'='false' and context->>'terms_valid'='true';
 result:=public.save_visit_reward_offer(gen_random_uuid(),br,'Actual offer without reward service',5,true,null);missing_offer:=(result->>'offer_id')::uuid;
 perform public.save_loyalty_policy(missing_policy,br,missing_offer,array[service],true);
 context:=public.get_loyalty_redemption_rules(missing_policy);assert context->'save_blockers' @> '["reward_service_missing"]';
 denied:=false;begin perform public.save_loyalty_redemption_rules(gen_random_uuid(),missing_policy,null,rules);exception when object_not_in_prerequisite_state then denied:=true;end;assert denied,'Unconfigured reward service enabled rules';
 execute 'reset role';
 assert (select count(*) from public.business_loyalty_transactions)=legacy_count;
 assert (select count(*) from private.canonical_loyalty_visits)=earned_count;
 assert (select count(*) from private.loyalty_visit_activations)=activation_count;
 assert (select count(*) from private.loyalty_visit_outbox)=outbox_count;
 assert (select md5(coalesce(string_agg(to_jsonb(i)::text,'' order by invoice_id),'')) from public.business_invoices i)=invoice_hash;
 raise notice 'PASS explicit owner-only versioned rules, immutable audit, strict replay/stale guards, actual reward/expiry validation and truthful disabled readiness; invoices/legacy/earning/activations unchanged';
end;$$;
rollback;
